from __future__ import annotations

from decimal import Decimal


# Eigene, neu formulierte Aufgaben. Die bereitgestellten Musterunterlagen dienen nur
# als Orientierung für Themenbreite, Situationsbezug und Aufgabentiefe. Es werden
# keine Originalaufgaben oder Originalformulierungen übernommen.


def _plain_number(Question, qid, category, topic, level, prompt, correct, explanation, hint=""):
    value = Decimal(str(correct)).quantize(Decimal("0.01"))
    text = f"{value:.2f}".replace(".", ",")
    return Question(qid, category, topic, level, prompt, "number", text, explanation, None, hint, Decimal("0.01"))


def build_exam_style_questions(Question, choice, number, money):
    out = []
    out += _accounting(Question, choice, number, money)
    out += _processes(choice)
    out += _german(choice)
    out += _correspondence(choice)
    out += _office(choice)
    return out


